mapper.select:
SELECT * FROM TBL_PROPERTY_RIGHT

    AND COMPANY_ID = #{query.companyId}
    AND RIGHT_TYPE = #{query.rightType}
    AND REGISTRATION_STATUS = #{query.registrationStatus}
    AND COMPANY_NAME LIKE CONCAT('%', #{query.companyName}, '%')

ORDER BY CREATE_TIME DESC

WITH RECURSIVE equity_chain AS (
    SELECT PROPERTY_ID, COMPANY_ID, COMPANY_NAME, PARENT_COMPANY_ID, HOLDING_RATIO, 1 AS LEVEL_NUM
    FROM TBL_PROPERTY_RIGHT WHERE COMPANY_ID = #{companyId}
    UNION ALL
    SELECT p.PROPERTY_ID, p.COMPANY_ID, p.COMPANY_NAME, p.PARENT_COMPANY_ID, p.HOLDING_RATIO, ec.LEVEL_NUM + 1
    FROM TBL_PROPERTY_RIGHT p INNER JOIN equity_chain ec ON p.PARENT_COMPANY_ID = ec.COMPANY_ID
    WHERE ec.LEVEL_NUM < #{maxLevel}
)
SELECT * FROM equity_chain ORDER BY LEVEL_NUM
